mapper.select:
SELECT t.ID, t.PRODUCT_CODE AS productCode, t.PRODUCT_DESC AS productDesc, t.SPEC_CODE AS specCode, t.MOULD_CODE AS mouldCode, t.SPECIFICATIONS AS specifications, t.PATTERN AS pattern, t.BRAND AS brand, t.MOULD_CATEGORY AS mouldCategory, sub.spec_count AS shareNum FROM T_MDM_PRODUCT_MODEL_RELATION t LEFT JOIN ( SELECT MOULD_CODE, COUNT(DISTINCT SPEC_CODE) AS spec_count FROM T_MDM_PRODUCT_MODEL_RELATION GROUP BY MOULD_CODE ) AS sub ON t.MOULD_CODE = sub.MOULD_CODE WHERE t.FACTORY_CODE = #{factoryCode}
AND t.SPEC_CODE IN
#{specCode}
AND EXISTS(SELECT 1 FROM T_MDM_MODEL_INFO m where t.FACTORY_CODE = m.FACTORY_CODE and m.MOULD_STATUS = 1)

SELECT DISTINCT mpmr.MOULD_CODE
  FROM t_mdm_product_model_relation mpmr
  LEFT JOIN t_mdm_model_info mmi
    ON mmi.MOULD_CODE = mpmr.MOULD_CODE
   AND mmi.MOULD_STATUS = 1
  LEFT JOIN t_mdm_mould_use_status mmus
    ON mmus.FACTORY_CODE = mmi.FACTORY_CODE
   AND mmus.MOULD_CODE = mmi.MOULD_CODE
 WHERE mmus.MOULD_STATUS = 1
   AND mmi.MOULD_STATUS = 1
   AND mpmr.PRODUCT_CODE = #{productCode,jdbcType=VARCHAR}
   AND mmus.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
   AND mmus.`YEAR` = #{year,jdbcType=DECIMAL}
   AND mmus.`MONTH` = #{month,jdbcType=DECIMAL}
   AND mmi.MOULD_NO= #{mouldNo,jdbcType=VARCHAR}
